insert into public.pgc_pages (slug, path, title, nav_label, meta_description, sort_order, published, review_state)
values ('home', '/', 'Proving Ground Capital (PGC) — Capital Built for Critical Technology', 'Home', 'Proving Ground Capital (PGC), the commercial arm of the Applied Research Institute, brings advisory expertise and aligned capital pathways to the convergence of biotechnology, microelectronics, and robotics shaping national security.', 10, true, 'draft')
