select id, 'hero', 'hero', null, 'Capital built for critical technology.', null, null, 'One convergence — biotechnology, microelectronics, and robotics — is defining national security. Proving Ground Capital (PGC), the commercial arm of the Applied Research Institute, is positioned ahead of the market: technology and commercialization advisory today, curated investment access as milestones are met.', null, '[]'::jsonb, '[{"label":"Partner With Proving Ground Capital (PGC)","href":"/contact/?intent=partner"},{"label":"Explore the Thesis","href":"/thesis/"}]'::jsonb, 'default', 10, true, 'draft'
  from public.pgc_pages where slug = 'home'
