insert into public.pgc_sections (page_id, section_key, kind, eyebrow, heading, heading_accent, kicker, lead, note, bullets, items, band, sort_order, published, review_state)
select id, 'about', 'rich', 'About Proving Ground Capital (PGC)', 'Public investment built the foundation.', 'Private capital must help scale what comes next.', null, 'Critical technologies often stall between research validation and commercial growth. Proving Ground Capital (PGC) helps companies navigate that gap through commercialization expertise, technical insight, strategic connections, and — as milestones are met — access to aligned capital.

Our focus spans biotechnology, microelectronics, robotics, and autonomy — including the technologies emerging where these sectors converge.', null, '[]'::jsonb, '[]'::jsonb, 'default', 20, true, 'draft'
  from public.pgc_pages where slug = 'home'
on conflict (page_id, section_key) do nothing;

insert into public.pgc_sections (page_id, section_key, kind, eyebrow, heading, heading_accent, kicker, lead, note, bullets, items, band, sort_order, published, review_state)
