insert into public.pgc_sections (page_id, section_key, kind, eyebrow, heading, heading_accent, kicker, lead, note, bullets, items, band, sort_order, published, review_state)
select id, 'why', 'rich', 'Why Proving Ground Capital (PGC)', 'Our edge is structural access —', 'not capital.', null, 'Proving Ground Capital (PGC) is built inside an established national innovation ecosystem, with earlier visibility into research-validated, government-aligned technologies.', null, '[]'::jsonb, '[{"eyebrow":"01","title":"Backbone of a CHIPS Act hub","text":"ARI is the backbone operator and ecosystem integrator of a CHIPS Act hub — convening government, universities, industry, and startups."},{"eyebrow":"02","title":"A network money can’t buy","text":"NSWC Crane, Purdue, Notre Dame, Pentagon program offices, and a growing member base of startups and primes."},{"eyebrow":"03","title":"Deal flow others never see","text":"Research-validated, government-aligned technologies surface inside the ecosystem long before open market processes."},{"eyebrow":"04","title":"Federal direction at our back","text":"Federal partners direct CHIPS hubs to build commercial sustainability alongside the federal mission."}]'::jsonb, 'default', 40, true, 'draft'
  from public.pgc_pages where slug = 'home'
