insert into public.pgc_sections (page_id, section_key, kind, eyebrow, heading, heading_accent, kicker, lead, note, bullets, items, band, sort_order, published, review_state)
select id, 'market-scale', 'rich', 'Market Scale', 'Security and growth', 'are the same bet.', null, 'These are not defense niches. They are the industrial base that grows GDP — and the same base a nation’s security ultimately rests on.', null, '[]'::jsonb, '[{"eyebrow":"/ 01","title":"$2.3T","text":"Combined global market today across microelectronics, biotechnology, and robotics — commercial demand, not a defense line item."},{"eyebrow":"/ 02","title":"~$5T","text":"The same three markets by 2030 on current forecasts — roughly double in five years, driven by AI, biologics, and automation."},{"eyebrow":"/ 03","title":"5.1%","text":"Of U.S. GDP from the bioeconomy alone — larger than the construction industry and on par with the information sector."},{"eyebrow":"/ 04","title":"26M","text":"U.S. workers in the 300+ downstream sectors that depend on semiconductors. Every direct chip job supports 5.7 more."}]'::jsonb, 'alt', 20, true, 'draft'
  from public.pgc_pages where slug = 'thesis'
on conflict (page_id, section_key) do nothing;

insert into public.pgc_sections (page_id, section_key, kind, eyebrow, heading, heading_accent, kicker, lead, note, bullets, items, band, sort_order, published, review_state)
select id, 'focus', 'rich', 'Our Focus', 'Three converging domains.', 'One national security lens.', null, null, null, '[]'::jsonb, '[{"eyebrow":"Domain 01","title":"MICRO","subtitle":"Microelectronics","text":"The spectrum, silicon and compute that decide who sees and acts first.\n\nAdvanced semiconductors & packaging, photonics, MEMS & sensing, trusted & radiation-hardened electronics.","bullets":[{"name":"EW & spectrum","detail":"Electromagnetic warfare, sensing"},{"name":"Edge compute","detail":"Processing at the point of need"},{"name":"Quantum","detail":"Sensing, timing, cryptography"}]},{"eyebrow":"Domain 02","title":"BIO","subtitle":"Life Sciences","text":"Domestic capacity to design, test and manufacture biology at scale.\n\nBiomanufacturing platforms, biosecurity & rapid diagnostics, synthetic biology & bio-materials.","bullets":[{"name":"Biomanufacturing","detail":"Onshore production capacity"},{"name":"Platforms","detail":"CRO / CDMO infrastructure"},{"name":"Drug development","detail":"Therapeutics & countermeasures"}]},{"eyebrow":"Domain 03","title":"ROBOTICS","subtitle":"Autonomy","text":"Autonomous systems, and the modern factories that build them.\n\nAutonomous ground, air & maritime systems, human-machine teaming & mission AI, unmanned platforms & edge autonomy.","bullets":[{"name":"AI & autonomy","detail":"Decision and control layers"},{"name":"Drones","detail":"Uncrewed air, ground, maritime"},{"name":"Manufacturing 4.0","detail":"Automated industrial production"}]}]'::jsonb, 'default', 30, true, 'draft'
  from public.pgc_pages where slug = 'thesis'
on conflict (page_id, section_key) do nothing;

insert into public.pgc_sections (page_id, section_key, kind, eyebrow, heading, heading_accent, kicker, lead, note, bullets, items, band, sort_order, published, review_state)
select id, 'intersection', 'rich', 'The Intersection', 'The intersection is our lens —', 'not a limit.', null, 'We back disruptive technology across all three arenas; the convergence is how we read government priorities and where our edge compounds. Modern capabilities do not operate in isolation: biosensors depend on advanced chips, autonomous systems combine sensing, computation, and action, and biomanufacturing increasingly relies on robotics, data, and intelligent systems.', null, '[{"name":"Biosensing & bio-integrated chips","detail":""},{"name":"Neuro- & physiological interfaces","detail":""},{"name":"Autonomous biomanufacturing","detail":""},{"name":"Distributed sensing for biosurveillance","detail":""},{"name":"Lab automation & AI-driven discovery","detail":""},{"name":"Dual-use platforms with program-of-record pull","detail":""}]'::jsonb, '[]'::jsonb, 'default', 40, true, 'draft'
  from public.pgc_pages where slug = 'thesis'
on conflict (page_id, section_key) do nothing;

