insert into public.pgc_team (name, role, bio, photo_url, photo_alt, linkedin_url, email, team_group, sort_order, published, review_state)
select 'Jeron Peoples', 'President & Chief Executive Officer', 'Sets investment strategy and leads the platform he architected. Previously led corporate development for Rolls-Royce Defense across hypersonics, novel nuclear, and electric propulsion, carrying commercial responsibility for over $1B in LibertyWorks revenue and pipeline, and sat on an investment committee overseeing $100M+ in annual allocations. At ARI, built the strategic link between capital markets and national security innovators. B.S., North Carolina A&T State University. IBJ 40 Under 40 (2025).', '/assets/img/team-jeron-peoples.webp', 'Jeron Peoples', 'https://www.linkedin.com/in/jeron-peoples-a951b080/', 'jeron.peoples@theari.us', 'principals', 10, true, 'draft'
where not exists (select 1 from public.pgc_team where name = 'Jeron Peoples');

